package io.github.jesterportfolio.hearth.survival.rpg;
import java.util.*;import java.util.concurrent.*;import java.security.MessageDigest;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.ItemStack;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.survival.VanillaPlayerFiles;
import io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role;
/** Keep the durable native preimage while death's audit is prepared; expose drops only after after-image save. */
public final class RpgDeath implements Listener,AutoCloseable {
 public java.util.function.Consumer<PlayerDeathEvent> beforeSplit=e->{};private final RpgRuntime r;public final DeathJournal journal;private boolean closed;
 private static final class Work{final Player player;final PlayerDeathEvent event;final ItemStack[] before,after;final List<ItemStack> drops;final Location at;final long points;final int orbs,oldLevel,oldTotal;final float oldExp;final Map<dev.aurelium.auraskills.api.skill.Skill,Double> auraBefore,auraAfter;final CompletableFuture<Void> done=new CompletableFuture<>();Object token;UUID respawnWorld;boolean released,live=true;
  Work(Player p,PlayerDeathEvent event,ItemStack[] before,ItemStack[] after,List<ItemStack> drops,long points,int orbs,Map<dev.aurelium.auraskills.api.skill.Skill,Double> auraBefore,Map<dev.aurelium.auraskills.api.skill.Skill,Double> auraAfter){this.player=p;this.event=event;this.before=before;this.after=after;this.drops=List.copyOf(drops);this.at=p.getLocation().clone();this.points=points;this.orbs=orbs;oldLevel=p.getLevel();oldTotal=p.getTotalExperience();oldExp=p.getExp();this.auraBefore=Map.copyOf(auraBefore);this.auraAfter=Map.copyOf(auraAfter);}}
 private final Map<UUID,Work> pending=new HashMap<>();private final Map<UUID,CompletableFuture<Void>> capacityPending=new HashMap<>();
 public RpgDeath(RpgRuntime r,UUID group){this.r=r;journal=new DeathJournal(r.plugin.getDataFolder().toPath().toAbsolutePath(),group);Bukkit.getPluginManager().registerEvents(this,r.plugin);}
 private static ItemStack[] copy(ItemStack[] input){return Arrays.stream(input).map(i->i==null?null:i.clone()).toArray(ItemStack[]::new);}
 public static String hash(ItemStack[] items){try{var digest=MessageDigest.getInstance("SHA-256");for(var item:items){byte[] b=item==null||item.isEmpty()?new byte[0]:item.serializeAsBytes();digest.update(java.nio.ByteBuffer.allocate(4).putInt(b.length).array());digest.update(b);}return HexFormat.of().formatHex(digest.digest());}catch(Exception e){throw new IllegalStateException(e);}}
 public static boolean equivalent(ItemStack[] first,ItemStack[] second){var codec=new io.github.jesterportfolio.hearth.inventory.PaperInventoryCodec();return codec.equivalent(codec.encode(first),codec.encode(second));}
 public boolean busy(UUID player){return pending.containsKey(player)||capacityPending.containsKey(player);}public CompletionStage<Void> settled(UUID player){var w=pending.get(player);return w==null?capacityPending.getOrDefault(player,CompletableFuture.completedFuture(null)):w.done;}
 @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p){Role role=r.role(p.getWorld());if(!r.policy.ready(role)||busy(p.getUniqueId())||journal.held(p.getUniqueId())||!r.aura.loaded(p.getUniqueId()))e.setCancelled(true);}}
 @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void death(PlayerDeathEvent e){Player p=e.getEntity();Role role=r.role(p.getWorld());if(!r.ready()||!r.policy.ready(role)||r.runtime.economy().transactions.busy(p.getUniqueId())||busy(p.getUniqueId())||journal.held(p.getUniqueId())||!r.aura.loaded(p.getUniqueId())||!e.getItemsToKeep().isEmpty()){e.setCancelled(true);return;}
  var nativeBefore=copy(p.getInventory().getContents());var top=p.getOpenInventory().getTopInventory();int[] inputs=DeathInventory.inputs(top.getType());var workspace=new ItemStack[1+inputs.length];workspace[0]=p.getItemOnCursor().clone();for(int i=0;i<inputs.length;i++){var item=top.getItem(inputs[i]);workspace[i+1]=item==null?null:item.clone();}var before=Arrays.copyOf(nativeBefore,nativeBefore.length+workspace.length);System.arraycopy(workspace,0,before,nativeBefore.length,workspace.length);
  final ItemStack[] packed;try{packed=DeathInventory.pack(before,nativeBefore.length);}catch(Exception noSpace){e.setCancelled(true);holdWorkspace(p,before);return;}
  try{beforeSplit.accept(e);var policy=r.policy.deaths().get(role);var slots=new ArrayList<RpgPolicy.Slot>();var extras=new ArrayList<ItemStack>();e.getDrops().forEach(item->extras.add(item.clone()));for(int i=0;i<before.length;i++){var item=before[i];if(item==null||item.isEmpty())continue;int left=item.getAmount();if(!e.getKeepInventory()&&i<nativeBefore.length)for(var drop:extras)if(left>0&&drop.isSimilar(item)){int n=Math.min(left,drop.getAmount());left-=n;drop.setAmount(drop.getAmount()-n);}slots.add(new RpgPolicy.Slot(i,hash(new ItemStack[]{item}),item.getAmount(),r.aura.itemRate(item,policy.dropRate()),r.isCharm(item)));}
   var split=r.policy.split(slots,r.policy.needsCharm(slots,policy),java.util.concurrent.ThreadLocalRandom.current());var retained=copy(before);var drops=new ArrayList<ItemStack>();for(var slot:slots){int kept=split.kept().getOrDefault(slot.index(),0),lost=split.dropped().getOrDefault(slot.index(),0);retained[slot.index()]=kept==0?null:before[slot.index()].asQuantity(kept);if(lost>0)drops.add(before[slot.index()].asQuantity(lost));}var after=DeathInventory.pack(retained,nativeBefore.length);
   boolean protectedVanilla=split.charmSlot()!=null&&r.policy.charmScopes().contains(RpgPolicy.CharmScope.VANILLA_XP),protectedAura=split.charmSlot()!=null&&r.policy.charmScopes().contains(RpgPolicy.CharmScope.AURA_XP);long points=VanillaXp.at(p.getLevel())+Math.round(p.getExp()*VanillaXp.next(p.getLevel())),next=points;int orbs=0;
   if(policy.loss()==RpgPolicy.XpLoss.VANILLA&&!protectedVanilla&&!e.getKeepLevel()){next=VanillaXp.at(e.getNewLevel())+e.getNewExp();orbs=e.getDroppedExp();}else if(policy.loss()==RpgPolicy.XpLoss.THIRD&&r.policy.vanillaLoss()&&!protectedVanilla){next=r.policy.xpScope()==RpgPolicy.XpScope.VANILLA_PROGRESS||r.policy.xpScope()==RpgPolicy.XpScope.BOTH_PROGRESS?VanillaXp.at(p.getLevel())+r.policy.remainingThird(points-VanillaXp.at(p.getLevel())):r.policy.remainingThird(points);if(r.policy.lostXpOrbs())orbs=Math.toIntExact(points-next);}
   var oldAura=new HashMap<dev.aurelium.auraskills.api.skill.Skill,Double>();var newAura=new HashMap<dev.aurelium.auraskills.api.skill.Skill,Double>();var user=r.aura.api.getUser(p.getUniqueId());if(policy.loss()==RpgPolicy.XpLoss.THIRD&&r.policy.auraLoss()&&!protectedAura)for(var skill:r.aura.api.getGlobalRegistry().getSkills())if(skill.isEnabled()){double amount=user.getSkillXp(skill);if(!Double.isFinite(amount)||amount<0)throw new IllegalStateException("DEATH_AURA_XP_DATA");double loss=switch(r.policy.rounding()){case FLOOR->Math.floor(amount/3);case CEIL->Math.ceil(amount/3);case NEAREST->Math.floor(amount/3+.5);default->throw new IllegalStateException("XP_ROUNDING_UNSET");};oldAura.put(skill,amount);newAura.put(skill,Math.max(0,amount-loss));}
   var work=new Work(p,e,packed,after,drops,next,orbs,oldAura,newAura);byte[] serialized=DeathJournal.encode(packed);
   // Workspace ownership is folded into native slots before the asynchronous boundary.
   p.setItemOnCursor(null);for(int input:inputs)top.setItem(input,null);p.getInventory().setContents(packed);VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);
   e.setKeepInventory(true);e.setKeepLevel(true);e.setDroppedExp(0);e.getDrops().clear();extras.stream().filter(item->!item.isEmpty()).forEach(e.getDrops()::add);pending.put(p.getUniqueId(),work);
   var ticket=journal.acquire(p.getUniqueId(),hash(packed),hash(after),serialized);
   // Normal death listeners replace the session token; capture that successor only after the event completes.
   Bukkit.getScheduler().runTask(r.plugin,()->{work.token=r.runtime.sessionToken(p);ticket.whenCompleteAsync((saved,error)->{if(error!=null){fail(work,error);return;}finish(work,saved);},r.owner);});
  }catch(Exception failure){e.setCancelled(true);var active=pending.remove(p.getUniqueId());if(active!=null)active.done.completeExceptionally(failure);try{p.getInventory().setContents(nativeBefore);p.setItemOnCursor(workspace[0]);for(int i=0;i<inputs.length;i++)top.setItem(inputs[i],workspace[i+1]);VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);}catch(Exception restore){failure.addSuppressed(restore);}r.hold(failure);}
 }
 private void holdWorkspace(Player p,ItemStack[] original){
  var completion=new CompletableFuture<Void>();capacityPending.put(p.getUniqueId(),completion);
  try{byte[] bytes=DeathJournal.encode(original);String before=hash(original);journal.acquire(p.getUniqueId(),before,before,bytes).whenCompleteAsync((ticket,error)->{
   // A cancelled death cannot become repeatable invulnerability: preserve the complete workspace and remove the actor from play.
   try{if(Bukkit.getPlayer(p.getUniqueId())==p){VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);p.kick(Component.text("사망 입력 보관 한도 초과 · 원본 보류 기록을 관리자에게 알려주세요."));}}catch(Exception failure){r.hold(failure);}finally{capacityPending.remove(p.getUniqueId(),completion);completion.completeExceptionally(error!=null?error:new IllegalStateException("DEATH_WORKSPACE_REVIEW"));}
  },r.owner);}catch(Exception failure){capacityPending.remove(p.getUniqueId(),completion);completion.completeExceptionally(failure);r.hold(failure);p.kick(Component.text("사망 원본 확인 필요 · 플레이를 보류합니다."));}
 }
 private boolean current(Work w){return !closed&&w.live&&pending.get(w.player.getUniqueId())==w&&w.token!=null&&r.runtime.current(w.player,w.token)&&(w.player.getWorld()==w.at.getWorld()||Objects.equals(w.respawnWorld,w.player.getWorld().getUID()))&&r.aura.loaded(w.player.getUniqueId())&&equivalent(w.player.getInventory().getContents(),w.before);}
 private void finish(Work w,DeathJournal.Ticket ticket){try{if(!current(w))throw new IllegalStateException("DEATH_SESSION_CHANGED");if(!w.event.isCancelled()){var user=r.aura.api.getUser(w.player.getUniqueId());for(var entry:w.auraBefore.entrySet())if(Double.compare(entry.getValue(),user.getSkillXp(entry.getKey()))!=0)throw new IllegalStateException("DEATH_AURA_CHANGED");w.player.getInventory().setContents(copy(w.after));var xp=VanillaXp.decode(w.points);w.player.setLevel(xp.level());w.player.setExp(xp.fraction());w.player.setTotalExperience(Math.toIntExact(w.points));w.auraAfter.forEach(user::setSkillXp);VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),w.player.getUniqueId(),w.player::saveData);w.released=true;for(var item:w.drops)w.at.getWorld().dropItem(w.at,item.clone());if(w.orbs>0)w.at.getWorld().spawn(w.at,ExperienceOrb.class,orb->orb.setExperience(w.orbs));}
   ticket.clean().whenCompleteAsync((v,error)->{if(error!=null)fail(w,error);else{pending.remove(w.player.getUniqueId(),w);w.done.complete(null);}},r.owner);
  }catch(Exception failure){if(!w.released&&r.runtime.current(w.player,w.token))try{w.player.getInventory().setContents(copy(w.before));w.player.setLevel(w.oldLevel);w.player.setExp(w.oldExp);w.player.setTotalExperience(w.oldTotal);w.auraBefore.forEach(r.aura.api.getUser(w.player.getUniqueId())::setSkillXp);VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),w.player.getUniqueId(),w.player::saveData);}catch(Exception restore){failure.addSuppressed(restore);}fail(w,failure);}}
 private void fail(Work w,Throwable failure){pending.remove(w.player.getUniqueId(),w);w.done.completeExceptionally(failure);r.plugin.getLogger().warning("HEARTH_DEATH_HELD player="+w.player.getUniqueId()+" original retained");if(Bukkit.getPlayer(w.player.getUniqueId())==w.player)w.player.kick(Component.text("사망 결과 확인 필요 · 원본 기록을 보존했습니다."));}
 @EventHandler public void respawn(PlayerRespawnEvent e){var w=pending.get(e.getPlayer().getUniqueId());if(w!=null)w.respawnWorld=e.getRespawnLocation().getWorld().getUID();}
 @EventHandler public void quit(PlayerQuitEvent e){var w=pending.get(e.getPlayer().getUniqueId());if(w!=null)w.live=false;}
 public CompletionStage<Void> drain(){return CompletableFuture.allOf(java.util.stream.Stream.concat(pending.values().stream().map(w->w.done),capacityPending.values().stream()).toArray(CompletableFuture[]::new)).handle((v,e)->null).thenCompose(v->journal.drain());}
 public void close(){closed=true;HandlerList.unregisterAll(this);for(var w:List.copyOf(pending.values())){w.live=false;w.done.completeExceptionally(new IllegalStateException("DEATH_CLOSED"));}pending.clear();capacityPending.values().forEach(f->f.completeExceptionally(new IllegalStateException("DEATH_CLOSED")));capacityPending.clear();journal.close();}
}
